import 'package:barcode/barcode.dart';

class BarcodeService {
  /// 주어진 바코드 유형과 데이터를 기반으로 SVG 문자열을 생성합니다.
  static String generateSvg({
    required Barcode barcodeType,
    required String data,
    double width = 300,
    double height = 100,
    double? fontHeight,
  }) {
    // toSvg() 메서드를 사용하여 SVG 문자열을 생성합니다.
    final svgString = barcodeType.toSvg(
      data,
      width: width,
      height: height,
      fontHeight: fontHeight,
    );
    return svgString;
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_svg/flutter_svg.dart';
import 'package:barcode/barcode.dart';
import '../services/barcode_service.dart';

class BarcodeDisplayWidget extends StatelessWidget {
  final Barcode barcodeType;
  final String data;
  final String title;
  final double width;
  final double height;

  const BarcodeDisplayWidget({
    super.key,
    required this.barcodeType,
    required this.data,
    required this.title,
    this.width = 300,
    this.height = 100,
  });

  @override
  Widget build(BuildContext context) {
    // 1. 서비스 호출: SVG 문자열 생성
    final svgContent = BarcodeService.generateSvg(
      barcodeType: barcodeType,
      data: data,
      width: width,
      height: height,
    );

    return Card(
      margin: const EdgeInsets.symmetric(vertical: 10),
      child: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(title, style: Theme.of(context).textTheme.titleMedium),
            const SizedBox(height: 10),
            // 2. SvgPicture.string을 사용하여 SVG 문자열 렌더링
            Center(
              child: SvgPicture.string(
                svgContent,
                width: width,
                height: height,
                fit: BoxFit.contain,
              ),
            ),
            const SizedBox(height: 10),
            Text('데이터: $data', style: const TextStyle(fontFamily: 'monospace', fontSize: 12)),
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:barcode/barcode.dart';
import 'widgets/barcode_display_widget.dart';

void main() => runApp(const BarcodeApp());

class BarcodeApp extends StatelessWidget {
  const BarcodeApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Barcode Demo',
      theme: ThemeData(useMaterial3: true),
      home: Scaffold(
        appBar: AppBar(title: const Text('Barcode Generation Demo')),
        body: SingleChildScrollView(
          padding: const EdgeInsets.all(16),
          child: Column(
            children: [
              // 1. QR Code 예제
              BarcodeDisplayWidget(
                title: 'QR Code',
                barcodeType: Barcode.qrCode(),
                data: 'https://pub.dev/packages/barcode',
                height: 200,
              ),

              // 2. Code 128 (공식 예제 반영)
              BarcodeDisplayWidget(
                title: 'Code 128 (Auto)',
                barcodeType: Barcode.code128(),
                data: 'BARCODE 128 TEST',
              ),

              // 3. EAN-13 (소매 제품 표준)
              BarcodeDisplayWidget(
                title: 'EAN-13 (12자리 입력, 13번째는 체크섬)',
                barcodeType: Barcode.ean13(drawEndChar: true),
                data: '590123412345',
              ),

              // 4. Data Matrix
              BarcodeDisplayWidget(
                title: 'Data Matrix',
                barcodeType: Barcode.dataMatrix(),
                data: 'DM-DATA-12345',
                height: 150,
              ),

              // 5. ITF (Interleaved 2 of 5)
              BarcodeDisplayWidget(
                title: 'ITF (짝수 길이 숫자만 가능)',
                barcodeType: Barcode.itf(),
                data: '987234',
              ),
            ],
          ),
        ),
      ),
    );
  }
}
